// lib/api.js
export async function fetchWind(lat, lon) {
    const res = await fetch(
        `https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&current_weather=true`
    );
    const data = await res.json();

    return {
        windSpeed: data.current_weather.windspeed
    };
}

// Simulated tide API (real NOAA integration would go here)
export async function fetchTide(beachId) {
    const phases = ["low", "mid", "high"];
    const phase = phases[Math.floor(Math.random() * phases.length)];

    return {
        phase,
        factor: phase === "high" ? 1.2 : phase === "mid" ? 1 : 0.85
    };
}

// Simulated wave data (NOAA buoy placeholder)
export async function fetchWave() {
    return {
        waveHeight: +(Math.random() * 2.5 + 0.5).toFixed(2),
        wavePeriod: +(6 + Math.random() * 7).toFixed(1)
    };
}
